-- 2255 🏋️ Exercises from the book "coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-attacking" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-attacking');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Find the free player in build-up v 3-4-3', 'phase_of_play', 'overload', 'in_possession', 19, 20, 'Practice for this tactical situation (Finding the free player v 3-4-3)', 'Conte (Juventus)', 'Building up from the back against a front three and finding the free man (holding midfielder or a centre back).', 'Two thirds of a pitch: a red GK zone and a blue build-up zone; 3 mini goals beyond the far red end line, with 2 black link players standing in 5 x 5 yd boxes between them.', 'GK starts; blacks play 4v3 in the blue zone and look to free the holding midfielder or a centre back, who dribbles over the red end line and passes into a mini goal. If the direct pass to the holding mid is cut off, a link player steps out and sets him first time. Whites who win it attack the GK zone and shoot.', 'Link players 1 touch then back to their box; GK 1 touch and must play back into the blue zone.', 'Change the white shape, e.g. 1 attacking mid + 2 forwards to mimic a 3-4-1-2.', 'Read where the free man is; use a link player when the lane is blocked; link player times his step so the set-back is first time.', 'GK + 4v3 + 2 outside link players', 10, 10, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Forward drops, spins and finishes', 'combination', 'unopposed', 'in_possession', 23, 24, 'Session 1 (Forwards a): Practice 1', 'Conte (Juventus)', 'Forward dropping off to open space then exploiting it, or receiving to feet and turning.', '30 x 40 yd: 4 back players (3 CBs + holding mid) behind small red cone gates, 2 forwards, two 6 x 6 yd white squares and two 5 x 10 yd blue target areas near goal; 2 big goals plus mini goals; coach feeds.', 'Coach passes to the middle CB and calls a number of passes; the back four complete them, then the last receiver dribbles through his cone gate, which cues the strong-side forward to drop through a yellow gate. If the ball carrier holds, the forward spins round a big cone into the blue area for a long pass and shot; if the pass comes early to feet, he turns and passes into a near mini goal.', 'Forwards 2 touches (receive and shoot/pass).', NULL, 'Decisive 2 touches with first touch out of the feet; receive on the half turn, body open; accurate passes and timed runs.', '8 players + coach', 8, 8, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 20),
  ('Forward drops or spins functional 4v2', 'phase_of_play', 'overload', 'in_possession', 25, 26, 'Session 1 (Forwards a): Practice 2', 'Conte (Juventus)', 'Reading whether the marker follows the dropping forward, then running in behind or turning, against a 3-4-3.', 'Two thirds of a pitch: white build-up zone 25 x 44 yd with 3 cone gates at its top, a red drop zone, a yellow forward zone flanked by two 5 x 10 yd blue areas; 2 black attacking mids wait outside, 2 black forwards v 2 white defenders in the yellow zone; GK in goal.', 'Coach/GK feeds a black in the white zone; blacks (4v2) dribble through a gate, which cues the strong-side forward to drop into the red zone. Marker follows: long pass into the blue area for the run and shot. Marker stays: pass to feet, forward turns and finds the other forward or the weak-side attacking mid; finish quickly. Whites winning it dribble over the blue end line.', 'Defenders may not enter the blue areas but can step out of the yellow zone once the pass to a forward is played.', 'Add a third defender in the yellow zone so blacks face a back three.', 'Read the defender and decide: follow = run into the blue area; stay = feet and turn. Max 2 touches, half turn.', '4v2 + 2 AMs, 2v2 forwards v defenders + GK', 11, 11, '2/3 pitch; white zone 25 x 44 yards', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Forward movement dynamic small sided game', 'phase_of_play', 'opposed', 'in_possession', 27, 27, 'Session 1 (Forwards a): Practice 3', 'Conte (Juventus)', 'Forwards creating space by dropping or turning inside a fuller game.', 'As practice 2 but a larger white zone with both black attacking mids inside: 6v5 in the white zone, forwards and defenders ahead, GK in big goal, 2 mini goals at the white end.', 'Coach/GK feeds a black; blacks find the free player (holding mid, or a CB if he is marked). On an open ball the strong-side forward drops to the red zone and either spins into the blue area or turns, depending on the marker; an attacking mid leaves the zone as an extra option. Whites who win it attack the 2 mini goals.', 'GK may join as an outside player: 1 touch or must play within 3 seconds.', 'Add 2 black wing backs as outside players on the flanks if 6v5 is too hard.', NULL, '6v5 in zone + forwards and defenders + GK', 16, 18, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Blind-side run onto long pass', 'combination', 'unopposed', 'in_possession', 29, 29, 'Session 2 (Forwards b): Practice 1', 'Conte (Juventus)', 'Weak-side forward running round the blind side of his marker to take a long pass and finish.', '30 x 40 yd: back four behind red cone gates, 2 forwards each beside a mannequin, two 5 x 10 yd blue areas near 2 goals; coach with balls.', 'Coach feeds the middle CB and calls a pass count; after the passes the last receiver dribbles through his gate, cueing the weak-side forward to curl round the blind side of his mannequin. The carrier plays a long pass into the blue area; forward finishes. 2 per position so players rest.', 'Pass must be received inside the blue area; forwards 2 touches (receive and shoot).', NULL, NULL, '8 players + coach (2 per forward position)', 8, 8, '30 x 40 yards', 36.6, 27.4, NULL, true, false, true, NULL, 50),
  ('Blind-side run functional practice 4(+2)v3', 'phase_of_play', 'overload', 'in_possession', 30, 30, 'Session 2 (Forwards b): Practice 2', 'Conte (Juventus)', 'Spotting time on the ball and timing a blind-side run in behind to score.', 'Two thirds of a pitch: white zone 25 x 44 yd with 4 blacks v 3 whites plus 2 black attacking mids outside; red zone ahead with 2 black forwards v 2 white defenders; two 5 x 10 yd blue areas; GK in goal.', 'Coach/GK feeds a black in the white zone; blacks free a player in space. When the weak-side forward sees the carrier has time he runs round the blind side of his defender into a blue area, takes the long pass and shoots. Whites who win it dribble over the blue end line.', 'The 2 defenders only defend inside the red zone.', 'Add 2 black wing backs as outside players at the sides if 4v3 is too hard.', NULL, '4(+2)v3 + 2v2 + GK', 14, 14, '2/3 pitch; white zone 25 x 44 yards', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Blind-side run with counter to mini goals', 'phase_of_play', 'opposed', 'in_possession', 31, 31, 'Session 2 (Forwards b): Practice 3', 'Conte (Juventus)', 'Making the blind-side run, receiving in space and finishing, with a punishment for a poor long pass.', 'As practice 2 with 3 white defenders in the red zone, coach with balls in the centre circle, 2 mini goals behind the white zone.', 'Same aim as before. If the long pass misses the blue area, the coach feeds a fresh ball to the whites in the white zone and they have 6 seconds to score in a mini goal.', 'The 3 white defenders only defend inside the red zone.', 'Add 2 black wing backs as outside players; all 3 practices can be set against other formations.', NULL, '4(+2)v3 + 2v3 + GK + coach', 15, 17, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Wing back and mid 2v1 near sideline', 'combination', 'overload', 'in_possession', 36, 36, 'Session 3 (Midfielders a): Practice 1', 'Conte (Juventus)', 'Creating and using a 2v1 near the touchline between attacking mid and wing back.', '40 x 50 yd: two 15 x 20 yd white wide zones with 15 x 5 yd blue end zones beyond; black wing back and 1 white defender start in a white zone, others on cones (CBs, mids, forwards); 2 goals at the far end; coach feeds.', 'Coach passes to a wide CB, who carries forward; the attacking mid moves into the white zone toward the line and with the wing back (helped by the forward as outside player) exploits the overload to dribble over the red line or receive in the blue zone, then crosses into the goal. Offside applies.', 'Outside players 1 touch; the white defender stays in the white zone.', NULL, NULL, '2v1 + outside forward per side, ~10 players + coach', 10, 12, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 80),
  ('Sideline overload to cross, side zones', 'phase_of_play', 'overload', 'in_possession', 37, 37, 'Session 3 (Midfielders a): Practice 2', 'Conte (Juventus)', 'Using the wide overload, then crossing for runners into a 3v3 in the box.', 'As practice 1 plus 3 white defenders at the edge of the box and a GK; 2 white side zones near the touchlines.', 'After beating the defender over the red line, the wide player crosses for the 2 black forwards and the far-side attacking mid; 3 white defenders try to stop them scoring 3v3. 2 players per forward and mid position for rest.', 'As practice 1.', NULL, 'Read the situation and choose correctly; accurate passing and synchronised movement.', '~16 players + GK', 16, 18, '40 x 50 yards (plus box)', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Sideline overload zonal 11v11 game', 'conditioned_game', 'opposed', 'in_possession', 38, 38, 'Session 3 (Midfielders a): Practice 3', 'Conte (Juventus)', 'Finding the free holding mid, then an attacking mid in the side zone to build a wide overload and cross.', '11v11 on 2/3 pitch: blue build-up zone with GK and 4v3; white side zones by the touchlines; red penalty zone; coaches on each flank.', 'GK starts 4v3 in the blue zone; blacks find the free holding mid who passes to an attacking mid dropping into a side zone. Coach counts to 3, then whites may enter the side zone too. Blacks use the overload to dribble over the red line or receive beyond it and cross for the 2 forwards and far-side mid; 3 white CBs defend. Whites counter: 5 s to score if won in the blue zone, 8 s elsewhere.', 'Whites in side zones stay in them; only the 3 white CBs may enter the box.', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Between the lines final pass, mannequins', 'combination', 'unopposed', 'in_possession', 41, 41, 'Session 4 (Midfielders c): Practice 1', 'Conte (Juventus)', 'Attacking mids keeping balance then receiving between the lines to play a final pass in behind.', 'Players on blue cones in their 3-5-2 slots (No.8 on a yellow cone) with red mannequins as a back line and midfield; big cones by each wide CB; cone gate for the holding mid; GK in goal.', 'Middle CB starts and the back four pass among themselves; a wide CB dribbles round his big cone while mids and wing backs adjust (strong-side wing back high, strong-side mid drops, weak-side mid high, weak-side wing back deep). After 3 passes the holding mid dribbles through the gate; the weak-side mid moves between the lines, receives and picks one of 3 runners in behind (2 forwards or advanced wing back).', NULL, 'Move the mannequins to copy other formations.', NULL, '10 outfield + GK', 10, 11, '2/3 of a pitch (as diagram)', NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Between the lines final pass v back five', 'phase_of_play', 'overload', 'in_possession', 42, 42, 'Session 4 (Midfielders c): Practice 2', 'Conte (Juventus)', 'Receiving between midfield and defence and playing a final pass in behind against live defenders.', 'As practice 1 but 5 red defenders (3 CBs in a blue zone, 2 wing backs) replace the back mannequins; midfield mannequins remain; GK.', 'Same pattern; the weak-side attacking mid gets between the lines and plays in a forward or wing back, now fully opposed, to score.', 'Red CBs stay in the blue zone unless the ball goes to a wing back in behind (offside on); red wing backs never enter the blue zone.', 'Use a red back four to rehearse other formations.', NULL, '10 + GK v 5 + GK', 17, 17, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Between the lines v 3-4-3 five-zone game', 'conditioned_game', 'opposed', 'in_possession', 43, 43, 'Session 4 (Midfielders c): Practice 3', 'Conte (Juventus)', 'Finding an attacking mid between the opposition midfield and defensive lines against a 3-4-3.', '11v11 on 2/3 of a pitch split into 5 zones: white low zone with GK and 4v3, a red midfield zone, a blue defensive zone, and wing back channels; goals at both ends.', 'GK starts 4v3 in the low zone; blacks look to pass into an attacking mid between the red and blue lines, then the whole team attacks to score. Reds who win it have 8 seconds to score.', 'Low-zone players stay there; 2 red mids stay in the red zone until a black mid receives between the lines; black wing backs and mids move freely; red wing backs stay between the red and blue zones; red CBs stay in the blue zone unless a wing back is found in behind (offside on).', NULL, NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Between the lines v 4-4-2 five-zone game', 'conditioned_game', 'opposed', 'in_possession', 44, 44, 'Session 4 (Midfielders c): Practice 4 (Variation)', 'Conte (Juventus)', 'Keeping balance and receiving between the lines against a 4-4-2.', 'Same 5-zone 11v11 set-up but the reds line up 4-4-2 with wingers kept wide.', 'Same aims and rules as practice 3. Once a black attacking mid is found between the lines, the red mids may leave the red zone to press. Reds winning it have 8 s to score.', 'As practice 3.', 'Shows how to adapt the game to any opposition formation.', NULL, '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Weak-side mid run between CB and WB', 'combination', 'unopposed', 'in_possession', 46, 46, 'Session 5 (Midfielders d): Practice 1', 'Conte (Juventus)', 'Weak-side attacking mid running into the gap between centre back and wing back for a long pass.', 'Cones and mannequins in the shown spots, back four behind red cone gates, two 8 x 8 yd blue areas (bigger for younger players) by the box; GK.', 'Back four circulate; as the ball switches, the attacking mids adjust (strong side drops to blue cone, weak side pushes to yellow cone). When a back player dribbles through his gate, the weak-side mid sprints into the blue area, takes the long pass and shoots.', 'Pass received in the blue area; 2 touches (receive and shoot).', NULL, NULL, '6 outfield + GK', 6, 7, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Weak-side mid run v 2 defenders', 'combination', 'opposed', 'in_possession', 47, 47, 'Session 5 (Midfielders d): Practice 2', 'Conte (Juventus)', 'Timing the run with an accurate long pass that defenders can now cut out.', 'As practice 1 with 2 white defenders in a yellow zone outside the box replacing 2 mannequins.', 'Same pattern; the long pass to the weak-side mid can now be intercepted by the defenders.', 'Pass received in the blue area, 2 touches to score; defenders stay in the yellow zone.', NULL, 'Well-timed run with accurate long pass; good first touch towards goal.', '6 + GK v 2', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Weak-side mid run functional with counter', 'phase_of_play', 'overload', 'in_possession', 48, 48, 'Session 5 (Midfielders d): Practice 3', 'Conte (Juventus)', 'Freeing the holding mid to switch a long pass to the weak-side attacking mid, with reds countering.', 'Large white zone split down the middle by a line (strong/weak side); 4 blacks + GK v 3 red forwards, black attacking mids outside as 1-touch helpers; 2 red mids, 2 red defenders in a yellow zone, blue areas by the box; 2 mini goals behind the white zone; coach with balls.', 'GK passes into the white zone for a 4(+3)v3; blacks free the holding mid, who plays a long pass to the weak-side mid to receive in the blue area and score. A poor or blocked pass: coach feeds a red mid into the white zone for a 5v4 counter with 6 s to hit a mini goal.', 'Attacking mid 2 touches; red defenders stay in the yellow zone.', NULL, NULL, '4(+3)v3 + 2 red mids + 2 red defenders + GK', 15, 15, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Strong-side mid run, wing back drops', 'combination', 'unopposed', 'in_possession', 50, 50, 'Session 6 (Midfielders e): Practice 1', 'Conte (Juventus)', 'Wing back and attacking mid synchronising so the mid runs into the strong-side gap and crosses.', 'Cones and 2 mannequins at the box; on each flank an 8 x 16 yd area split into blue and white halves; back three behind cone gates, wing backs, attacking mids, 2 forwards; GK.', 'Back three pass; wing back and mid move together (wing back high in blue, mid deep; wing back deep in white, mid higher). When the strong-side wing back is high, the wide CB dribbles through his gate; the wing back drops, the mid makes a diagonal run into the blue area, takes a long pass and crosses for a forward attacking near or far post.', 'Pass must be received inside the blue area.', NULL, NULL, '9 outfield + GK', 9, 10, 'Flank areas 8 x 16 yards', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Strong-side gap run v live defenders', 'phase_of_play', 'overload', 'in_possession', 51, 52, 'Session 6 (Midfielders e): Practice 2', 'Conte (Juventus)', 'Reading the opposing wing back to choose the long pass to the running mid or the short pass to the wing back.', 'As practice 1 plus 3 white defenders in a red zone and 2 white wing backs marking the black wing backs.', 'Wide CB carries through the gate when his wing back is high; wing back drops, mid runs into the blue area. If the white wing back follows, pass direct to the mid; if not, short to the wing back, who draws the defender then plays the mid in behind. Mid crosses or combines with the forwards to score.', 'Pass received in the blue area; white defenders stay in the red zone.', NULL, 'CBs read the wing back position and pass accurately; wing back and mid synchronised; mid times run, good first touch, combination, cross or finish.', '9 + GK v 5 + GK', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Strong-side gap zonal game', 'conditioned_game', 'opposed', 'in_possession', 53, 53, 'Session 6 (Midfielders e): Practice 3', 'Conte (Juventus)', 'Creating and exploiting space near the touchline with the attacking mid''s forward run in a full-team game.', 'As practice 2 plus 2 white midfielders and 3 white forwards; large yellow middle zone, blue/white flank areas, red attacking zone; goals at both ends.', 'GK passes to a black in the yellow zone. Attacking mids move off their wing back (wing back in blue = stay in yellow; wing back drops = mid pushes out). Blacks aim to open and use the blue areas in either of the two ways from practice 2.', 'Same rules as practice 2.', 'If whites block the long passes, the weak-side attacking mid receives between the lines and attacks centrally.', NULL, '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Two forwards diagonal run or lay-off', 'combination', 'unopposed', 'in_possession', 57, 58, 'Session 7 (Forwards in centre): Practice 1', 'Conte (Juventus)', 'Forwards working together: one drops, the other runs into the freed space or receives a lay-off.', '40 x 50 yd with cones and 4 goals (2 big, 2 mini); back four behind cone gates; one forward in each 8 x 16 yd blue area about 10 yd apart; white central area between them.', 'Back four pass; when a back player carries to his gate, the strong-side forward drops out of his area and the weak-side forward reacts. Quick weak-side forward: long pass into the top of the blue area, run and shoot. Tall weak-side forward: pass to feet in the lower part, he lays off to the quick forward running into the white area, who passes into a mini goal. 2 players per forward slot.', 'Passes must reach the correct part of the blue area; forwards 2 touches.', NULL, 'Coordinate the two forwards'' movement and time the run for the long pass; strong first touch toward goal or a clean lay-off.', '8 players', 8, 8, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 210),
  ('Forwards'' collaboration runs vs passive markers', 'combination', 'passive', 'in_possession', 59, 60, 'The 2 Forwards Combining in the Centre (b) Session: Practice 2', 'Conte (Juventus)', 'Forwards create and use space in behind with a diagonal run or a lay-off.', 'Full pitch with two blue boxes in front of the box and a white central area; one white defender in each blue box, 4 black back players, 2 black attacking midfielders, 2 forwards, goalkeeper.', 'Back four circulate until one carries forward; the attacking mids position off the ball. If the slower target forward drops, the quicker one runs diagonally into the upper blue box to receive and shoot; if the target man receives the long ball low in the box he lays off into the white area for the other forward, making a 3v2 to goal.', 'Passes must land in the correct part of the blue box (upper or lower); forwards max 2 touches. Strong-side defender tracks his forward; weak-side defender may not enter the other box.', NULL, NULL, '8 attackers + 2 defenders + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Forwards'' collaboration in 6v5 red-zone SSG', 'small_sided_game', 'opposed', 'in_possession', 61, 61, 'The 2 Forwards Combining in the Centre (b) Session: Practice 3', 'Conte (Juventus)', 'Find the free player in build-up, then use the forwards'' drop/diagonal run or lay-off to score.', 'Large red zone in own half with 2 mini goals at the back; blue boxes and white area up top with 2 forwards and 2 white defenders; coaches with balls on each side; GK in big goal.', 'GK plays into the red zone for a 6v5; blacks find a free player with time, the strong-side forward drops with his marker and the other attacks the blue box on a long pass to shoot or lay off. Whites who win it in the red zone have 6 seconds to score in the mini goals.', 'Defenders follow markers but cannot defend the far-side blue box. Failed pass or combination: coach feeds whites for a 5v5 counter with 6 seconds.', NULL, NULL, '6v5 + 2v2 + GK', 16, 18, 'Large zone plus top of pitch', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Receive between lines, lay-off combination', 'combination', 'unopposed', 'in_possession', 63, 63, 'Receiving Between the Lines and Quick Passing Combination With a Lay Off Pass: Practice 1', 'Conte (Juventus)', 'Forward receives between the lines and the pair combine with a lay-off for the attacking midfielder.', '40 x 50 yd with 2 mini goals, a cone gate, two 8 x 8 yd blue boxes about 15 yd apart each holding a forward, and a central white area; 4 back players, 2 attacking mids.', 'Back four circulate; when one carries forward the strong-side forward drops out of his box. Ball carrier through the gate passes to the forward, who plays first time to the other forward and moves to the white area for the lay-off, then slips the attacking mid or the curving forward to shoot in a mini goal.', 'Lay-off must be received inside the white area.', NULL, 'Spare players in the attacking-mid role keep it continuous with rest.', '8', 8, 10, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 240),
  ('Lay-off combination between lines, passive defenders', 'combination', 'passive', 'in_possession', 64, 64, 'Receiving Between the Lines and Quick Passing Combination With a Lay Off Pass: Practice 2', 'Conte (Juventus)', 'Receiving between the lines and quick lay-off combination play.', 'Same as Practice 1 on a full pitch to goal with GK; one passive white defender in each blue box shadowing the forwards.', 'Same sequence: drop, first-time pass to the other forward, lay-off into the white area, final pass to the attacking mid or curving forward who finishes.', 'Lay-off must be received in the white area; defenders follow but do not tackle.', NULL, 'Time the attacking mid''s run with the forward''s curved run; weight the lay-off so the receiver can pass first time.', '8 + 2 passive + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Lay-off combination in 6v5 red-zone SSG', 'small_sided_game', 'opposed', 'in_possession', 65, 65, 'Receiving Between the Lines and Quick Passing Combination With a Lay Off Pass: Practice 3', 'Conte (Juventus)', 'Find a free player then play the forwards'' one-two/lay-off to attack the goal.', 'Red zone with 2 mini goals behind; blue boxes and white area up front with 2 forwards and 2 white defenders; coaches each side; GK.', 'GK plays in for 6v5; free player passes to the dropping forward, who combines with the other forward and gets the return in the white area; attacking mid joins for a 3v2 to goal.', 'Failed lay-off: coach feeds whites who have 6 seconds to score in a mini goal (5v5).', NULL, NULL, '6v5 + 2v2 + GK', 16, 18, 'Large zone plus top of pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Forwards'' quick one-two in behind', 'combination', 'unopposed', 'in_possession', 67, 67, 'Receiving Between the Lines and Quick One-Two Combination Between the Forwards: Practice 1', 'Conte (Juventus)', 'Receive between the lines then one-two to get in behind.', '40 x 50 yd, 2 mini goals, cone gates, mannequins; 3 back players and one forward in each of two 8 x 8 yd blue boxes about 15 yd apart.', 'Back three circulate; when a wide back carries through the gate, strong-side forward drops in front of the mannequin and the weak-side forward shifts across. Pass to one forward, quick one-two, return played into the runner''s path in the blue box to score in a mini goal.', NULL, NULL, NULL, '7', 7, 9, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 270),
  ('One-two in behind when wing back steps', 'combination', 'passive', 'in_possession', 68, 68, 'Receiving Between the Lines and Quick One-Two Combination Between the Forwards: Practice 2', 'Conte (Juventus)', 'Use the one-two between forwards when the opposing wing back pushes up.', 'Full pitch to goal; forwards on yellow cones marked by 2 white defenders; 2 black wing backs in white side areas, 2 white wing backs on yellow cones; 3 back players.', 'Back three circulate, forwards shift; a centre back carries forward. Only if the white wing back steps into the white area to mark does he pass to the forward, who one-twos with the other forward and attacks the blue box to shoot; otherwise the ball goes back to the middle.', 'Defenders follow but do not win the ball; final pass must be received in the blue box.', NULL, NULL, '7 + 4 + GK', 12, 12, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('One-two combination in dynamic SSG', 'small_sided_game', 'opposed', 'in_possession', 69, 69, 'Receiving Between the Lines and Quick One-Two Combination Between the Forwards: Practice 3', 'Conte (Juventus)', 'Recognise the trigger (wing back stepping) for the forwards'' one-two in a game.', 'Red zone 5(+2)v4 with 2 mini goals, yellow zone 2v3 up top with blue boxes, wing backs outside white areas; coach holds a red and a yellow cone.', 'Coach feeds the red zone; blacks find a free player, strong-side forward drops and one-twos with the other into the blue box to score. Red cone raised = white wing back steps up to press; yellow = he stays deep and blacks keep the ball and wait.', 'White defenders cannot enter the blue boxes but can defend outside the yellow zone. Whites who win it in red or yellow zones have 6-8 seconds to score in a mini goal.', 'If the moment does not come, use the lay-off combination from the earlier session.', NULL, '5(+2)v4 + 2v3 + GK', 18, 20, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Overload to receive unmarked between lines', 'combination', 'unopposed', 'in_possession', 72, 72, 'Creating an Overload to Receive Unmarked in Between the Lines: Practice 1', 'Conte (Juventus)', 'Forwards create a 2v1 overload in front of the defence so one receives unmarked and turns.', '40 x 50 yd with 4 mannequins and 4 mini goals; blue and white 5 x 10 yd areas in the centre; forwards start on white cones; 4 back players.', 'Back players circulate with at least 3 touches; forwards shift to the ball. When it reaches the holding mid, the deeper forward steps into the blue area and the other into the white, overloading the mannequins; holding mid passes into the blue area. Receiver turns and passes diagonally to a side mini goal, or finds the other forward curving away to score in an end goal.', 'Back players use at least 3 touches.', NULL, NULL, '6', 6, 8, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 300),
  ('Overload between lines plus final pass', 'combination', 'passive', 'in_possession', 73, 73, 'Creating an Overload to Receive Unmarked in Between the Lines + Final Pass: Practice 2', 'Conte (Juventus)', 'Create an overload, receive unmarked and turn to face goal, then play the final ball.', 'Full pitch to goal with GK; as Practice 1 plus 2 attacking mids on yellow cones and 2 passive red defenders in the white zone; mannequins.', 'Back players circulate, forwards and mids position to the ball; forwards overload the centre and one receives from the holding mid in the blue area, turns and plays the attacking mid or the other forward in to shoot.', 'Red defenders may only enter the blue area after the forward receives and may not defend outside the white zone.', NULL, NULL, '8 + 2 passive + GK', 11, 11, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Overload between lines in dynamic SSG', 'small_sided_game', 'opposed', 'in_possession', 74, 74, 'Creating an Overload to Receive Unmarked in a Dynamic Small Sided Game: Practice 3', 'Conte (Juventus)', 'Build up, play into a forward who has created an overload, and attack 2v3 to goal.', 'Large red zone with 2 white side zones and 2 mini goals; GK starts; 6(+3)v4 below, 2v3 in the white zone up top.', 'GK plays a black in the red zone; blacks pass into the overloading forward in the blue area and attack the 3 defenders, with attacking mid and wing backs running forward; if forwards are blocked the ball can go wide to a wing back.', 'Reds enter the blue area only after the forward receives and cannot defend outside the white zone; reds who win it in the red zone have 6 seconds to score.', NULL, NULL, '6(+3)v4 + 2v3 + GK', 18, 20, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Wide lay-off combination and final pass', 'combination', 'unopposed', 'in_possession', 77, 78, 'Quick Combination With a Lay Off Pass, Final Pass in Behind and Finishing: Practice 1', 'Conte (Juventus)', 'Combination play near the sideline using a lay-off.', '40 x 50 yd with cones, mannequins, a large goal and mini goals; middle centre back with balls, two wide centre backs, 2 forwards, blue area in front of the mannequins.', 'Middle centre back passes wide; forwards shift. Diagram 1: wide back carries, a forward drops, plays first time to the other and runs to the blue area for the lay-off, then passes into a wide mini goal, a central mini goal or the other forward who shoots in the big goal. Diagram 2: ball goes straight to the advanced forward who lays off to the dropping one.', 'Successful only if the lay-off is received in the blue area.', NULL, 'Two extra players waiting in the forward spots for rest and flow.', '5', 5, 7, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 330),
  ('Wide lay-off combination vs passive defenders', 'combination', 'passive', 'in_possession', 79, 79, 'Quick Combination With a Lay Off Pass, Final Pass in Behind and Finishing: Practice 2', 'Conte (Juventus)', 'Near-sideline combination with a lay-off and a pass in behind.', 'Full pitch with cones and mannequins; 3 centre backs, 2 forwards in a white zone with passive red defenders, 2 attacking mids, 2 wing backs, blue cone gate wide, GK.', 'Centre backs circulate, forwards and mids shift. When the wing back dribbles through the blue gate, strong-side forward drops; ball goes to him or straight to the far forward, who lays off into the blue area; the receiver picks the best runner (attacking mid, wing back or forward) in behind.', 'Red defenders are passive and never try to win the ball.', NULL, NULL, '9 + passive defenders + GK', 13, 14, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Wide lay-off combination in SSG', 'small_sided_game', 'opposed', 'in_possession', 80, 80, 'Quick Combination With a Lay Off Pass and Finishing in a Small Sided Game: Practice 3', 'Conte (Juventus)', 'After build-up, release a wing back and use the forwards'' lay-off to attack.', 'Large red zone 5(+2)v4 with a goal behind for GK; 2 wing backs as outside players; 2v3 in the white zone up top with a blue area.', 'GK plays a black; after 3 passes the ball goes to a wing back who carries forward; forwards in the white zone combine via a lay-off into the blue area and attack, ending with a cross or shot. Reds who win it in the red zone must score within 6 seconds.', 'Reds in the white zone do not block the pass from the wing back and cannot enter the blue area; they cannot defend outside the white zone unless the ball goes to the weak-side wing back; lay-off must be received in the blue area.', NULL, NULL, '5(+2)v4 + 2v3 + GK', 17, 19, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Forward drops, attacking mid runs weak side', 'combination', 'unopposed', 'in_possession', 85, 85, 'The Forward Creating Space for the Attacking Midfielder On the Weak Side and Finishing: Practice 1', 'Conte (Juventus)', 'Synchronised movement of forward and attacking mid to create and use weak-side space.', '40 x 50 yd to a goal with GK; red cone gates for the back players, a mannequin, two 10 x 8 yd blue boxes, 2 forwards, 2 attacking mids, holding mid.', 'Back players circulate until one dribbles through a red gate; the forward on the far side drops to make space and the attacking mid behind him runs into the blue box. Wide back plays a long diagonal into the box and the mid shoots.', 'Attacking mid receives in the blue box and has only 2 touches.', NULL, 'Two players per attacking-mid spot for flow and rest.', '8 + GK', 9, 11, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 360),
  ('Weak-side run for long pass vs 3 defenders', 'combination', 'opposed', 'in_possession', 86, 86, 'The Forward Creating Space for the Attacking Midfielder On the Weak Side and Finishing: Practice 2', 'Conte (Juventus)', 'Exploit weak-side space with a forward''s drop and a midfielder''s run onto a long pass.', 'Two-thirds pitch; white zone with 2 forwards v 3 red defenders and blue boxes either side; 4 back players, 2 attacking mids, GK.', 'Blacks build up and everyone moves with the ball; as the holding mid approaches the red gate, the weak-side forward drops and the weak-side attacking mid runs into the blue box for the long pass, then shoots.', 'Reds move freely in the white zone but cannot enter the blue boxes; long pass must be received in the blue box; mid uses 2 touches.', NULL, 'Understand how movements sync with the ball; open body shape and well-timed runs.', '8v3 + GK', 12, 12, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Weak-side space for attacking mid SSG', 'small_sided_game', 'opposed', 'in_possession', 87, 87, 'The Forward Creating Space for the Attacking Midfielder On the Weak Side in a Dynamic SSG: Practice 3', 'Conte (Juventus)', 'Find time for a long pass into weak-side space opened by a dropping forward.', 'Yellow zone 5v4 with 2 mini goals behind; white zone 2v3 with blue boxes; red middle zone where 2 attacking mids start; coaches each side; GK.', 'GK starts; blacks in the yellow zone look for time to play long into the weak-side blue box as the forwards drop to open it, and the attacking mid runs in to receive and score.', 'Defenders follow opponents but cannot enter the blue boxes; attacking mids may enter yellow and white zones (one per zone at a time), 1 touch in yellow, 2 in blue. Inaccurate long pass: coach feeds whites in the yellow zone, 6 seconds to score 4v5.', NULL, NULL, '5v4 + 2v3 + 2 mids + GK', 17, 19, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Wing back drops, third-man run', 'combination', 'unopposed', 'in_possession', 89, 89, 'Creating and Exploiting Space With Synchronised Movements and 3rd Man Run: Practice 1', 'Conte (Juventus)', 'Strong-side space created by the wing back dropping, used with a third-man run.', '40 x 50 yd to goal with GK and 2 mannequins; 3 centre backs, wing backs in white side areas, 2 forwards, 2 attacking mids, blue boxes.', 'Centre backs circulate; when a wide one carries forward, that side''s wing back drops out of the white area, the attacking mid runs forward, and the forward drops to play the pass first time into the blue box for the mid. Mid then crosses low to the far forward''s diagonal run or cuts back to the other forward.', NULL, NULL, 'Two players per forward and attacking-mid spot for rest.', '9 + GK', 10, 14, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 390),
  ('Third-man run vs 3 defenders', 'combination', 'opposed', 'in_possession', 90, 90, 'Creating and Exploiting Space With Synchronised Movements and 3rd Man Run: Practice 2', 'Conte (Juventus)', 'Synchronised movement to exploit strong-side space with a third-man run.', 'Two-thirds pitch, same layout as Practice 1 with 3 live white defenders replacing the mannequins.', 'Same sequence: wide centre back carries, wing back drops, forward plays the attacking mid in behind, finish from the cross or cut-back.', 'Defenders can go anywhere except the 2 blue boxes and try to win the ball.', NULL, 'Sync movements with the ball, open body shape, well-timed runs.', '9v3 + GK', 13, 17, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('7v7 third-man run SSG', 'small_sided_game', 'opposed', 'in_possession', 91, 91, 'Creating and Exploiting Space With Synchronised Movements and 3rd Man Run in a SSG: Practice 3', 'Conte (Juventus)', 'Read when the third-man combination is on and when to keep the ball.', '70 x 50 yd, two goals with GKs; 7v7 in a yellow zone; 2 black and 2 white wing backs in white side areas; blue boxes up top.', 'Blacks keep it; when a wide centre back has the ball, the wing back drops; if his marker follows, play the third-man run from earlier; if the marker stays, keep possession. Whites who win it have 6 seconds to score.', 'White defenders cannot enter the blue boxes in the first phase but may leave the yellow zone once the third-man combination is on.', NULL, NULL, '7v7 + 2v2 wing backs + 2 GKs', 20, 20, '70 x 50 yards', 64.0, 45.7, NULL, true, true, true, NULL, 410),
  ('Find the free player in build-up', 'phase_of_play', 'opposed', 'in_possession', 98, 98, 'Moving the Ball to the Free Player When Building Up From the Back in a Functional Practice', 'Conte (Juventus)', 'Build from the back against a 3-4-1-2 and find the free player.', 'Two-thirds pitch; 4v3 in a blue zone with a red end line; 2 outside players (attacking mids) in yellow boxes; 3 mini goals beyond; whites attack the big goal with GK.', 'GK plays a black in the blue zone; blacks cross the red line and then pass into a mini goal, e.g. by playing forward to an attacking mid who lays back to the free player. Whites who win it attack the GK; blacks who regain pass back to the GK to restart.', 'Whites may enter the white area once they win the ball.', 'Adapt the shape to any opponent formation.', NULL, '4v3 + 2 outside + GK', 10, 12, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('4v3 overload near the sideline', 'phase_of_play', 'opposed', 'in_possession', 105, 105, 'Creating and Exploiting a Numerical Advantage Near the Sideline: Practice 1', 'Conte (Juventus)', 'Centre back steps in to create a 4v3 on the flank and break through.', '40 x 50 yd with two 20 x 30 yd white side zones, each with a 20 x 7 yd blue end zone, a central goal and 2 wide mini goals; coach serves.', 'Coach passes to a wide centre back who dribbles into the white zone for 4v3 as the attacking mid shifts wide. Option 1: dribble over the red end line or receive in the blue zone, then the wing back crosses low to a mini goal. Option 2: dribble through the red side line and score in the central goal.', 'White defenders cannot defend outside the white zone.', NULL, NULL, '4v3 per side', 14, 16, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 430),
  ('Flank overload functional practice to goal', 'phase_of_play', 'opposed', 'in_possession', 106, 106, 'Creating and Exploiting a Numerical Advantage Near the Sideline in a Functional Practice: Practice 2', 'Conte (Juventus)', 'Create a flank overload, then cross or play through centrally.', 'Two-thirds pitch with the two 20 x 30 yd side zones split by a central blue area where 2 forwards face 3 defenders; GK.', 'Same as Practice 1; after the 4v3 on the flank, cross (Option 1) or go through the red side line (Option 2), when the forward slips the other forward or the weak-side attacking mid.', 'Offside applies. One defender may track a forward into a side zone. After a cross, white defenders may leave the blue area; on Option 2 they defend only in it. Only the weak-side attacking mid may leave his white zone.', NULL, NULL, 'Full teams v 3 defenders + side 4v3s + GK', 18, 20, 'Two-thirds of pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Flank overload 5-zone game', 'small_sided_game', 'opposed', 'in_possession', 107, 107, 'Creating a Numerical Advantage Near the Sideline in a 5 Zone Game: Practice 3', 'Conte (Juventus)', 'Create and exploit a sideline numerical advantage in a game.', 'Two goals with GKs; 4v3 in a yellow back zone plus a 4v3 in each white side zone; central and penalty zones.', 'Same aims as Practices 1-2: overload a flank, then cross or play through the side line to score. Whites who win it have 6 seconds to score with no zone limits.', 'Offside applies. On a cross whites may defend the box; on Option 2 they cannot defend inside the box. Only the weak-side attacking mid may leave his white zone.', NULL, NULL, '4v3 + 4v3 + 4v3 + 2 GKs', 22, 24, 'Full or two-thirds pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Wide 2v1 overload into end zone v 4-4-2', 'phase_of_play', 'overload', 'in_possession', 128, 128, 'Session (Creating a Numerical Advantage Near the Sideline): Practice 1', 'Conte (Juventus)', 'Create and use a 2v1 near the touchline against a 4-4-2 shape, with the attacking midfielder sliding wide to receive.', '40 x 50 yard area with two 15 x 20 yard white channels by the touchlines, each with a 15 x 7 yard blue end zone behind a red line; two mini goals on the end line. Black back three, wing backs, attacking midfielders and two forwards; white defenders sit in the white channels; coach with balls at the bottom.', 'Coach feeds a wide centre back who steps up with the ball; that triggers the attacking midfielder to drift wide behind the white wide player. When the white defender steps in to press, the blacks use the 2v1 (wing back plus midfielder, with help from a forward) to cross over the red line or get a pass into the blue zone, then the wing back pulls a low cross into a mini goal.', 'Forwards outside the channels are one-touch. White defenders may only defend inside the white channels.', NULL, NULL, '8 attackers v 4 defenders + coach', 12, 14, '40 x 50 yards', 45.7, 36.6, NULL, true, false, true, NULL, 460),
  ('Wide overload and cross, functional 2/3 pitch', 'phase_of_play', 'overload', 'in_possession', 129, 129, 'Session (Creating a Numerical Advantage Near the Sideline): Practice 2', 'Conte (Juventus)', 'Same wide 2v1 against the 4-4-2, now finishing with a cross for runners into a full goal.', 'Two thirds of a pitch, full goal with keeper; white wide channels by each touchline ending at a red line; coach serves from the bottom.', 'Coach plays to a centre back who carries forward; attacking midfielder shifts wide and combines with the wing back to beat the white defender, who may enter the channel to press. Instead of an end zone, the ball is received beyond the red line and crossed into the box for forwards and midfielders arriving.', 'Forwards one-touch outside; white defenders stay in the white channels; offside applies.', NULL, 'The forward need not always help but should check away and then attack the box.', 'approx 8 attackers v 4 defenders + GK', 13, 15, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Zonal game: wide 2v1 v 4-4-2', 'small_sided_game', 'opposed', 'in_possession', 130, 130, 'Session (Creating a Numerical Advantage Near the Sideline): Practice 3', 'Conte (Juventus)', 'Exploit the wide 2v1 against a 4-4-2 inside a zoned game to two goals, before the covering midfielder gets across.', 'Two thirds of a pitch with a goal and keeper at each end. Central yellow zone with a 4v2 build-up; white side zones with a 2v1 each side; two white midfielders start in small red boxes; blue penalty-area zone.', 'Blacks build up 4v2 from their keeper, a centre back advances and the attacking midfielder drops wide to receive. White midfielders start in the red boxes and try to cut the pass; if they fail they may step into the side zone to make it 2v2, so the blacks must play quickly. If whites win the ball they counter to the far goal.', 'Forwards one-touch; white defenders in the side zones stay there; only white centre backs may enter the blue penalty area (black runners free); whites must score within 6 seconds of winning it.', NULL, NULL, 'two teams, approx 11v10 + 2 GKs', 18, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Run behind the full back, unopposed pattern', 'combination', 'passive', 'in_possession', 133, 134, 'Session (Exploiting Space Behind the Full Back): Practice 1 (Unopposed)', 'Conte (Juventus)', 'Read the passive full back and get the attacking midfielder or wing back into the space behind him for a cross.', '40 x 50 yard area, full goal and keeper; red target box on each flank with a passive white full back inside; mannequins in midfield; back three at the bottom, wing backs wide, attacking midfielders and two forwards, two per attacking role.', 'Back three pass across; a wide centre back carries forward. If the full back leaves the red box to mark the wing back, the centre back passes straight into the box for the attacking midfielder''s run, who crosses for the forwards'' near/far post runs. If the full back stays, the ball goes to the wing back, the full back steps out, and the midfielder runs into the box to receive and cross.', NULL, NULL, 'Doubled players in forward and midfield roles keep it continuous with recovery time.', 'approx 13 + 2 passive defenders + GK', 12, 16, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 490),
  ('Behind the full back with defenders, 2/3 pitch', 'phase_of_play', 'opposed', 'in_possession', 135, 135, 'Session (Exploiting Space Behind the Full Back): Practice 2 (Opposed)', 'Conte (Juventus)', 'Same decision on space behind the full back, now with centre backs defending the cross.', 'Two thirds of a pitch, goal and keeper; red boxes on both flanks with a white full back; yellow band marking the start positions of wing backs and attacking midfielders; two white centre backs added v the two forwards.', 'Centre back passes to a wide centre back who steps on. If the full back follows the dropping wing back, the pass goes straight into the red box for the midfielder; if he stays, the ball goes to the free wing back. Cross for the forwards'' near and far post runs against the two white centre backs.', NULL, NULL, 'Wide centre back must read the picture; runs synchronised to lose markers; accurate short and long passes, crosses and finishing.', 'approx 13 attackers v 4 defenders + GK', 16, 18, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Zonal game: behind the full back', 'small_sided_game', 'opposed', 'in_possession', 136, 136, 'Session (Exploiting Space Behind the Full Back): Practice 3 (Zonal Game)', 'Conte (Juventus)', 'Apply the wing back / attacking midfielder rotation to exploit the full back inside a game with zone rules.', 'Two thirds of a pitch, goal and keeper at each end. Blue build-up zone with 4(+1)v6; yellow band ahead holds the wing backs and one attacking midfielder; white full backs start in red boxes on the flanks.', 'Blacks build in the blue zone (one attacking midfielder supports there) and look for the same triggers: if the full back follows the dropping wing back, pass into the red box; if he stays, find the wing back. Whites who win the ball in the blue zone counter to the other goal.', 'White centre backs may not enter the red boxes; white midfielders may not enter the yellow band until a pass goes to a wing back; white full backs must leave the red box once a wing back receives; whites score within 6 seconds.', NULL, NULL, 'two teams, approx 11v10 + 2 GKs', 18, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Wing back balance passing pattern', 'passing_unopposed', 'unopposed', 'in_possession', 168, 168, 'Practice for this tactical situation (Balanced Positioning of the Wing Backs)', 'Conte (Juventus)', 'Teach the wing backs to stagger (one high, one deep) during build-up so the team is ready if the ball is lost.', 'Half pitch; back three and the holding midfielder by red cones, a big red cone/mannequin ahead of each wide centre back, high and low blue cones for each wing back.', 'Middle centre back plays to a wide centre back, who dribbles at the big cone; this sends his wing back up to the high cone while the far wing back drops to the low cone and the other two defenders slide across. He then passes back to the middle or to the holding midfielder and the ball is moved to the other side, where the roles swap.', NULL, NULL, 'Defenders reset positions every time the ball changes side.', '6 (3 CBs, DM, 2 wing backs)', 6, 8, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 520),
  ('Wing back and midfielder balance pattern', 'passing_unopposed', 'unopposed', 'in_possession', 171, 171, 'Session (Retaining Balance Near the Sideline): Practice 1 (Unopposed)', 'Conte (Juventus)', 'Pair each wing back with the attacking midfielder on his side so one goes high when the other drops, keeping balance wide.', 'Half pitch; back three and holding midfielder, wing backs and two attacking midfielders, big red cones/mannequins, high and low blue and yellow cones for wing backs and midfielders.', 'As in the previous pattern, a wide centre back carries at the big cone, prompting his wing back to go high or drop. If the wing back drops low, the attacking midfielder on that side goes high; if the wing back goes high, the midfielder drops low. The far-side pair do the opposite, and the other defenders and holding midfielder slide across before the ball switches.', NULL, NULL, 'Weight and accuracy of passes keep the rhythm; drop and push movements happen together.', '8 (3 CBs, DM, 2 wing backs, 2 AMs)', 8, 10, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 530),
  ('Wide balance and react to loss', 'transition', 'opposed', 'to_defend', 172, 173, 'Session (Retaining Balance Near the Sideline): Practice 2', 'Conte (Juventus)', 'Keep wide balance in build-up and react straight away when the ball is lost near the touchline.', 'Two thirds of a pitch; blue zones on each flank with white players inside, yellow zones in front of them ending at a red end line; black back three, wing backs and attacking midfielders.', 'Centre back passes to a wide centre back who steps on; the wing back goes high or drops and the attacking midfielder balances him. The wide centre back then deliberately gives the ball away with a loose aerial ball to the white full back or a soft ground pass the white midfielder intercepts, and the blacks must immediately defend to stop whites dribbling or passing over the red end line.', 'Whites score by getting over the red end line.', NULL, 'Stay balanced to be ready for losing it; instant defensive reaction on the loss.', 'approx 7 attackers v 6 defenders', 12, 15, '2/3 pitch', NULL, NULL, NULL, false, false, true, NULL, 540),
  ('Attacking midfielders hold balance in build-up', 'passing_unopposed', 'unopposed', 'in_possession', 177, 177, 'Balanced Positioning of the Attacking Midfielders: Practice 1 (Unopposed)', 'Conte (Juventus)', 'Attacking midfielders keep a balanced shape (one deeper, one high) during build-up so the team is ready if the ball is lost.', 'Back three and the holding midfielder on red cones around halfway; two attacking midfielders in the middle third with 4 mannequins and high/low blue cones to move to.', 'Centre back passes to a wide centre back who carries forward towards a big cone; that triggers the strong-side attacking midfielder to drop to a low blue cone (wider if the holding mid is already on that side, more central if not) while the weak-side attacking midfielder pushes up to the high cone.', NULL, 'Repeat to both sides.', 'Movements are triggered by the ball carrier; always one attacking midfielder deep and one high.', '6 (3 defenders, holding mid, 2 attacking mids)', 6, 6, 'Half pitch', NULL, NULL, NULL, false, false, true, NULL, 550),
  ('Balanced midfield and quick counter-press', 'transition', 'opposed', 'to_defend', 178, 178, 'Balanced Positioning of the Attacking Midfielders: Practice 2', 'Conte (Juventus)', 'Keep balanced positions while building up and react straight away to stop the opponents breaking when the ball is lost.', 'Back three and holding midfielder start on red cones; two black attacking midfielders in a marked zone ahead of them with white midfielders inside; a red end line across the back of the zone.', 'Blacks circulate across the back; when a wide centre back carries forward the attacking midfielders take balanced positions. The carrier then deliberately gives the ball away to a white midfielder, and the black attacking midfielders try to stop the whites getting the ball through the red end line.', 'Whites score by moving the ball through the red end line.', NULL, 'Stay balanced at all times to be ready for the negative transition; react instantly when possession is lost.', '6 blacks v 2-3 whites', 8, 9, NULL, NULL, NULL, NULL, false, false, true, NULL, 560),
  ('Balanced midfield transition game 5v6 zone', 'transition', 'opposed', 'to_defend', 179, 179, 'Balanced Positioning of the Attacking Midfielders: Practice 3', 'Conte (Juventus)', 'Retain midfield balance in attack and use quick defensive reactions to win the ball back after losing it.', 'Pitch split in three: black back three in a blue zone, a central white zone with 5 blacks v 6 whites, and a red area in front of goal holding 2 black forwards and a goalkeeper.', 'Black defenders look for a low through pass into the forwards in the red area (1 point) or a pass into the white zone, after which the blacks try to carry the ball over the blue end line (1 point). If the whites win it they try to get the ball through the red end line at the other end within 6 seconds while the blacks counter-press.', 'Back three may not play long direct balls to the forwards; long balls into the white zone are allowed. Whites have 6 seconds to score.', NULL, 'Keep balance throughout the attack; immediate pressure on the new ball carrier.', '10 blacks v 6 whites + GK', 17, 17, 'About two-thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Keep numerical advantage at the back', 'passing_opposed', 'passive', 'in_possession', 183, 184, 'Numerical Advantage at the Back: Practice 1', 'Conte (Juventus)', 'Back three and wing backs keep an extra player at the back during build-up against three forwards.', 'Back three pass and shift in their own half with 3 white forwards taking up defensive positions (not tackling); two wing backs start at white cones; two mini goals beyond red cones further up the pitch.', 'When a wide centre back has the ball the strong-side wing back pushes on to receive while the weak-side wing back drops into the zone level with the deepest forward. The strong-side wing back receives, dribbles past the red cone and finishes in a mini goal; restart from the central defender to the other side.', 'White forwards are passive and do not try to win the ball.', 'Variation v 2 forwards + attacking midfielder (4-3-1-2 / 3-4-1-2): weak-side wing back drops level with the attacking midfielder if he is behind the holding mid, otherwise holds his position by the cone.', 'Weak-side wing back reads the situation and reacts; synchronised, balanced movement of the whole unit.', '6 v 3 (passive)', 9, 9, 'Half pitch', NULL, NULL, NULL, true, false, true, NULL, 580),
  ('Numerical advantage at back, then defend counter', 'transition', 'opposed', 'to_defend', 185, 185, 'Numerical Advantage at the Back: Practice 2', 'Conte (Juventus)', 'Keep the extra man at the back while building up and defend the counter attack when the ball is lost.', 'Blacks (back three, holding mid, two wing backs) v whites set up as a 3-4-3: 3 forwards in the white zone with the black defenders, 4 white midfielders in a blue zone with the wing backs; goalkeeper in goal.', 'Goalkeeper plays to a black defender and the blacks circulate 4v3. When a wide defender carries forward, his wing back pushes on and the weak-side wing back drops level with the deepest forward. The carrier then deliberately passes to a white midfielder, who feeds a white forward, and the whites counter attack against the goalkeeper while the blacks recover.', 'Once the whites win the ball zone restrictions are lifted.', NULL, 'Wing back on the weak side protects the back line; immediate reaction on losing the ball.', '6 blacks v 7 whites + GK', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 590),
  ('11v11 keep the spare defender game', 'conditioned_game', 'opposed', 'to_defend', 186, 186, 'Numerical Advantage at the Back: Practice 3', 'Conte (Juventus)', 'Attack while always keeping a numerical advantage at the back so the counter can be stopped.', 'Full pitch 11v11 (adjust to numbers) with a marked white zone in the black team''s defensive half where the white forwards start.', 'Blacks start with the ball and try to score but must keep an extra player in the white zone during their attack. When the whites win it they pass to one of their forwards in the white zone and try to score within 6 seconds. Restart from the black goalkeeper after a shot or ball out of play.', 'Whites have 6 seconds to score after winning the ball.', 'Adjust to play against different opposition formations.', 'Defenders only go aggressively to the ball when the advantage at the back is in place.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Direct counter with long diagonal pass', 'combination', 'unopposed', 'to_attack', 222, 222, 'Direct Counter Attack: Practice 1 (Unopposed)', 'Conte (Juventus)', 'On winning the ball, play quickly forward with a long diagonal pass into space behind the wide centre backs for the forwards to finish.', 'Blacks in a 3-5-2 on blue cones; 2 white wing backs on red cones wide; 3 mannequins as the opposing back line in front of goal with blue target boxes outside them on each flank; coach in the middle with balls; goalkeeper.', 'Coach passes to a white wing back; blacks shift to the ball and the strong-side wing back presses. The white player hits a long ball to the back three; the receiver clears or passes to a midfielder. A pass to an attacking midfielder is laid off to the holding midfielder, who (or who directly) plays a long diagonal into a blue box attacked by a curving forward, who finishes.', 'Forward receives inside the blue area and shoots, ideally in 2 touches.', 'Use 2 mannequins instead of 3 to simulate a back four.', 'Forwards make curved runs on the blind side of the wide centre back into space by the sideline.', '11 blacks incl. GK + 2 white feeders', 13, 13, 'Two-thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Direct counter transition game 11v11', 'transition', 'opposed', 'to_attack', 223, 223, 'Direct Counter Attack: Practice 2', 'Conte (Juventus)', 'Counter attack quickly after regaining possession with a long pass into the channels.', '11v11 (adjust to numbers). A white zone across the pitch in front of the white defence bounded by a red line, with blue target areas on each flank beyond it.', 'White goalkeeper starts, whites build up aiming for their wing backs while blacks shift to the ball. When the blacks win it they find a midfielder who hits a long pass for a forward into a blue area; blacks try to score within 6 seconds.', 'In the 6 seconds white defenders may only defend beyond the red line (leave the white area) after the long pass has been played; after 6 seconds no restrictions.', 'Adjust to play against any formation.', NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Indirect counter with switch of play', 'combination', 'unopposed', 'to_attack', 229, 230, 'Indirect Counter Attack: Practice 1 (Unopposed)', 'Conte (Juventus)', 'After winning the ball on one side, switch quickly to the weak-side wing back and attack the flank against a back four.', 'As the direct counter practice but with the attacking midfielders'' cones set wider and 2 extra mannequins beside the black wing backs; blue target boxes on each flank; 2 white full backs on yellow cones; coach with balls; goalkeeper.', 'Coach feeds a white full back; strong-side attacking mid presses, strong-side wing back stays by his mannequin, weak-side wing back drops a few yards. Long ball to the back three is cleared to a midfielder, then via the holding mid a long switch into the blue box for the weak-side wing back; the attacking mid on that side bursts up the flank, receives a through ball and crosses for the 2 forwards.', NULL, 'Variation: on the clearance to the holding mid a forward shows, lays off to the weak-side attacking mid, ball goes to the wing back in the blue box, and the other forward runs the flank and crosses for the attacking mid and the other forward.', 'Weak-side wing back stays high enough to receive the switch; runners attack the box.', '11 blacks incl. GK + 2 white feeders', 13, 13, 'Two-thirds of a pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Indirect counter transition game 11v11', 'transition', 'opposed', 'to_attack', 231, 231, 'Indirect Counter Attack: Practice 2', 'Conte (Juventus)', 'Win the ball and switch to the weak-side wing back to create a 4v4 and score quickly.', '11v11 (adjust to numbers) with a white zone across the pitch in front of the white goal.', 'White goalkeeper starts, whites build up towards their full backs while blacks shift. On winning possession the blacks switch to the weak-side wing back directly or via a team-mate; the weak-side attacking mid joins him in the white zone to make 4v4 and blacks try to score within 8 seconds.', 'For 8 seconds white midfielders and forwards may not enter the white zone; after that everyone defends freely.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 640)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-the-juventus-3-5-2-tactical-analysis-and-sessions-attacking') b;
